    if(action==='clear-memo'&&await confirmAction('업무 메모 내용을 모두 비웁니다. 필요하면 먼저 TXT 또는 JSON으로 백업해 주세요.','업무 메모를 비울까요?','비우기')){state.workMemo='';state.workMemoDelta=null;persisted('업무 메모를 비웠어요.');render();}
